def ini(p):
    out={}
    for line in p.read_text(encoding='utf-8-sig').splitlines():
        if '=' in line and not line.lstrip().startswith(';'):
            k,v=line.split('=',1);out[k.strip()]=v.strip()
    return out
def normal(s):return re.sub(r'\s+',' ',s).strip().lower()
def build(tables,upstream,dest):
    source=ini(upstream/'rewrite/data/original/stringtable_cn.ini')
    cn=ini(tables/'stringtable_cn.ini');en=ini(tables/'stringtable_en.ini')
    dictionary={}
    for values in [cn,source]:
        for key,value in values.items():
            if re.search('[\u3400-\u9fff]',value) and key in en:
                translated=en[key];dictionary[value]=RU.get(normal(translated),translated)
    dictionary.update(CUSTOM)
    data={'language':'ru-with-original-english','source_version':'1.4.50','source_xapk_sha256':'917f808540755ed3fae695d1212efc647d18e236dce13c19e54ed27f947603f4','dictionary':dictionary,'russian':RU,'labels':LABELS}
    dest.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print('Prepared',len(dictionary),'original and custom translations; Russian menus, original English narrative.')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--tables',type=Path,required=True);p.add_argument('--upstream',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();build(a.tables,a.upstream,a.output)
